export default function LisbonGoalTracker({ goals }) {
      const rows = Array.isArray(goals) ? goals : [];
      const lisbon = rows.find(g => g.name && g.name.toLowerCase().includes("lisbon")) || null;

      const [depositAmount, setDepositAmount] = React.useState("");
      const [status, setStatus] = React.useState(null);

      const saved = lisbon ? lisbon.saved : 0;
      const target = lisbon ? lisbon.target : 0;
      const ratio = target > 0 ? Math.min(saved / target, 1) : 0;
      const remaining = Math.max(target - saved, 0);

      async function handleDeposit() {
        const dollars = parseFloat(depositAmount);
        if (!dollars || dollars <= 0) {
          setStatus({ kind: "error", message: "Enter a valid amount." });
          return;
        }
        const cents = Math.round(dollars * 100);
        setStatus({ kind: "pending", message: "Submitting transfer..." });
        try {
          const result = await tools.host_transferMoney({
            amount: cents,
            recipient_name: lisbon ? lisbon.name : "Lisbon savings goal",
            memo: "Lisbon savings goal deposit"
          });
          if (result && result.status === "pending-approval") {
            setStatus({ kind: "awaiting", message: "Awaiting your approval to complete the transfer." });
          } else {
            setStatus({ kind: "success", message: "Transfer submitted successfully." });
          }
          setDepositAmount("");
        } catch (e) {
          setStatus({ kind: "error", message: "Transfer could not be submitted. Please try again." });
        }
      }

      const borderColor = "var(--vendo-color-border)";
      const textColor = "var(--vendo-color-text)";
      const mutedColor = "var(--vendo-color-muted)";
      const accentColor = "var(--vendo-color-accent)";
      const surfaceColor = "var(--vendo-color-surface)";
      const radius = "var(--vendo-radius-medium)";
      const fontFamily = "var(--vendo-font-family)";

      if (!lisbon) {
        return (
          <div style={{
            background: surfaceColor,
            border: `1px solid ${borderColor}`,
            borderRadius: radius,
            padding: "32px 24px",
            fontFamily,
            color: mutedColor,
            textAlign: "center"
          }}>
            <div style={{ fontSize: "15px" }}>No Lisbon goal found. Create a savings goal named "Lisbon" to track it here.</div>
          </div>
        );
      }

      return (
        <div style={{ fontFamily, color: textColor, display: "flex", flexDirection: "column", gap: "20px" }}>
          {/* Hero card */}
          <div style={{
            background: surfaceColor,
            border: `1px solid ${borderColor}`,
            borderRadius: radius,
            padding: "32px 28px",
            display: "flex",
            flexDirection: "column",
            gap: "20px"
          }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
              <div>
                <div style={{ fontSize: "13px", color: mutedColor, marginBottom: "6px", letterSpacing: "0.02em" }}>Saved so far</div>
                <div style={{ fontSize: "40px", fontWeight: "700", letterSpacing: "-0.02em", lineHeight: 1 }}>
                  {fmt.money(saved)}
                </div>
              </div>
              <div style={{ textAlign: "right" }}>
                <div style={{ fontSize: "13px", color: mutedColor, marginBottom: "6px" }}>Target</div>
                <div style={{ fontSize: "22px", fontWeight: "600" }}>{fmt.money(target)}</div>
              </div>
            </div>

            {/* Progress bar */}
            <div>
              <div style={{
                height: "8px",
                background: "var(--vendo-color-border)",
                borderRadius: "99px",
                overflow: "hidden"
              }}>
                <div style={{
                  height: "100%",
                  width: `${Math.round(ratio * 100)}%`,
                  background: accentColor,
                  borderRadius: "99px",
                  transition: "width 0.6s cubic-bezier(0.4,0,0.2,1)"
                }} />
              </div>
              <div style={{ display: "flex", justifyContent: "space-between", marginTop: "8px" }}>
                <span style={{ fontSize: "13px", color: mutedColor }}>{Math.round(ratio * 100)}% complete</span>
                <span style={{ fontSize: "13px", color: mutedColor }}>{fmt.money(remaining)} to go</span>
              </div>
            </div>
          </div>

          {/* Deposit card */}
          <div style={{
            background: surfaceColor,
            border: `1px solid ${borderColor}`,
            borderRadius: radius,
            padding: "24px 28px",
            display: "flex",
            flexDirection: "column",
            gap: "16px"
          }}>
            <div style={{ fontSize: "15px", fontWeight: "600" }}>Add to goal</div>
            <div style={{ display: "flex", gap: "12px", alignItems: "flex-end" }}>
              <div style={{ flex: 1 }}>
                <label style={{ display: "block", fontSize: "13px", color: mutedColor, marginBottom: "6px" }}>Amount (USD)</label>
                <input
                  type="number"
                  min="1"
                  step="0.01"
                  placeholder="0.00"
                  value={depositAmount}
                  onChange={e => { setDepositAmount(e.target.value); setStatus(null); }}
                  style={{
                    width: "100%",
                    padding: "10px 14px",
                    fontSize: "15px",
                    border: `1px solid ${borderColor}`,
                    borderRadius: "var(--vendo-radius-small)",
                    fontFamily,
                    color: textColor,
                    background: surfaceColor,
                    outline: "none",
                    boxSizing: "border-box"
                  }}
                />
              </div>
              <button
                onClick={handleDeposit}
                disabled={!depositAmount || status?.kind === "pending" || status?.kind === "awaiting"}
                style={{
                  padding: "10px 22px",
                  background: accentColor,
                  color: "var(--vendo-color-accent-text)",
                  border: "none",
                  borderRadius: "var(--vendo-radius-small)",
                  fontSize: "15px",
                  fontWeight: "600",
                  cursor: "pointer",
                  fontFamily,
                  opacity: (!depositAmount || status?.kind === "pending" || status?.kind === "awaiting") ? 0.5 : 1,
                  transition: "opacity 0.2s"
                }}
              >
                {status?.kind === "pending" ? "Sending..." : "Transfer"}
              </button>
            </div>

            {status && (
              <div style={{
                fontSize: "13px",
                color: status.kind === "error" ? "var(--vendo-color-danger)" : status.kind === "success" ? "#1a7f4b" : mutedColor,
                padding: "10px 14px",
                background: status.kind === "error" ? "#fff1f0" : status.kind === "success" ? "#f0faf4" : "#f5f5f3",
                borderRadius: "var(--vendo-radius-small)",
                border: `1px solid ${borderColor}`
              }}>
                {status.message}
              </div>
            )}
          </div>

          {/* Stats row */}
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
            <div style={{
              background: surfaceColor,
              border: `1px solid ${borderColor}`,
              borderRadius: radius,
              padding: "20px 20px"
            }}>
              <div style={{ fontSize: "13px", color: mutedColor, marginBottom: "6px" }}>Remaining</div>
              <div style={{ fontSize: "22px", fontWeight: "700" }}>{fmt.money(remaining)}</div>
            </div>
            <div style={{
              background: surfaceColor,
              border: `1px solid ${borderColor}`,
              borderRadius: radius,
              padding: "20px 20px"
            }}>
              <div style={{ fontSize: "13px", color: mutedColor, marginBottom: "6px" }}>Progress</div>
              <div style={{ fontSize: "22px", fontWeight: "700" }}>{Math.round(ratio * 100)}%</div>
            </div>
          </div>
        </div>
      );
    }

components.BudgetDiningProgress:
export default function BudgetDiningProgress({ budgets }) {
      const rows = Array.isArray(budgets) ? budgets : [];
      const dining = rows.find(b => b.category === "dining");

      if (!dining) {
        return (
          <Text variant="caption" text="No dining budget configured. Set one up in your budget settings."/>
        );
      }

      const { limit, spent, category } = dining;
      const ratio = limit > 0 ? Math.min(spent / limit, 1) : 0;
      const remaining = limit - spent;
      const overBudget = spent > limit;

      return (
        <Stack gap={3}>
          <Row gap={4}>
            <Stack gap={1}>
              <Text variant="caption" text="Spent"/>
              <Text variant="heading" text={fmt.money(spent)}/>
            </Stack>
            <Stack gap={1}>
              <Text variant="caption" text="Limit"/>
              <Text variant="heading" text={fmt.money(limit)}/>
            </Stack>
            <Stack gap={1}>
              <Text variant="caption" text={overBudget ? "Over by" : "Remaining"}/>
              <Text
                variant="heading"
                text={overBudget ? fmt.money(Math.abs(remaining)) : fmt.money(remaining)}
              />
            </Stack>
          </Row>
          <Progress
            value={ratio}
            label="Dining budget used"
            showValue
            tone={overBudget ? "danger" : ratio > 0.8 ? "warning" : "default"}
          />
          {overBudget && (
            <Callout tone="warning" title="Over budget">
              You have exceeded your dining budget this period.
            </Callout>
          )}
        </Stack>
      );
    }

components.MoneyHqBills:
export default function MoneyHqBills({ bills }) {
  const [mounted, setMounted] = React.useState(false);
  React.useEffect(() => { requestAnimationFrame(() => setMounted(true)); }, []);

  const capitalize = (s) => s.charAt(0).toUpperCase() + s.slice(1);
  const rows = (Array.isArray(bills) ? bills : [])
    .filter((b) => b && typeof b.payeeName === "string" && typeof b.amount === "number" && typeof b.nextDate === "string")
    .map((b) => ({
      id: b.id ?? b.payeeName,
      name: b.payeeName,
      amount: Math.abs(b.amount),
      nextDate: b.nextDate,
      cadence: typeof b.cadence === "string" ? capitalize(b.cadence) : "",
    }));
  if (rows.length === 0) return null;

  const fmt$ = (cents) => {
    const abs = Math.abs(cents / 100);
    return (cents < 0 ? "-" : "") + "$" + abs.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  };

  const daysUntil = (iso) => {
    const due = new Date(iso);
    return Math.round((due.getTime() - Date.now()) / 86400000);
  };

  const fmtDate = (iso) => new Date(iso).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });

  const sectionStyle = (delay) => ({
    opacity: mounted ? 1 : 0,
    transform: mounted ? "translateY(0)" : "translateY(18px)",
    transition: `opacity 0.55s ease ${delay}ms, transform 0.55s ease ${delay}ms`,
  });

  return (
    <div style={{ fontFamily: "system-ui, -apple-system, Segoe UI, Roboto, sans-serif", background: "#F5F6FA", padding: "0 0 48px" }}>
      <div style={{ maxWidth: 680, margin: "0 auto", padding: "0 16px" }}>
        {/* Section 4: Upcoming Bills */}
        <div style={sectionStyle(60)}>
          <div style={{ marginTop: 32, marginBottom: 14 }}>
            <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: "0.1em", textTransform: "uppercase", color: "#908C85" }}>Upcoming Bills</div>
          </div>
          <div style={{ background: "#fff", border: "1px solid #E8E9EE", borderRadius: 14, overflow: "hidden", boxShadow: "0 1px 4px rgba(0,0,0,0.04)" }}>
            {rows.map((b, i) => {
              const days = daysUntil(b.nextDate);
              const warn = days <= 7;
              return (
                <div key={b.id} style={{ display: "flex", alignItems: "center", gap: 12, padding: "16px 18px", borderBottom: i < rows.length - 1 ? "1px solid #F0F1F5" : "none" }}>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 14, fontWeight: 600, color: "#111" }}>{b.name}</div>
                    <div style={{ fontSize: 12, color: "#908C85", marginTop: 2 }}>{b.cadence}</div>
                  </div>
                  <div style={{ textAlign: "right" }}>
                    <div style={{ fontSize: 15, fontWeight: 700, color: "#111" }}>{fmt$(b.amount)}</div>
                    <div style={{ display: "flex", alignItems: "center", gap: 6, marginTop: 3, justifyContent: "flex-end" }}>
                      <div style={{ fontSize: 12, color: "#908C85" }}>{fmtDate(b.nextDate)}</div>
                      <div style={{ background: warn ? "#FEF3C7" : "#F0F1F5", color: warn ? "#D97706" : "#908C85", borderRadius: 20, padding: "2px 8px", fontSize: 11, fontWeight: 600, whiteSpace: "nowrap" }}>
                        {days <= 0 ? "Today" : days === 1 ? "Tomorrow" : `${days}d`}
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

