  React.useEffect(() => { requestAnimationFrame(() => setMounted(true)); }, []);

  const rows = Array.isArray(accounts) ? accounts : [];
  if (rows.length === 0) return null;

  const fmt$ = (cents) => {
    const abs = Math.abs(cents / 100);
    return (cents < 0 ? "-" : "") + "$" + abs.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  };

  const kindLabel = { checking: "Checking", savings: "Savings", credit: "Credit", investing: "Investing" };
  const kindColor = { checking: "#1DB87A", savings: "#3B82F6", credit: "#EF4444", investing: "#8B5CF6" };

  const sectionStyle = (delay) => ({
    opacity: mounted ? 1 : 0,
    transform: mounted ? "translateY(0)" : "translateY(18px)",
    transition: `opacity 0.55s ease ${delay}ms, transform 0.55s ease ${delay}ms`,
  });

  const sparkH = 36;
  const sparkW = 120;
  const netWorth = rows.reduce((sum, acc) => sum + (typeof acc.balance === "number" ? acc.balance : 0), 0);

  return (
    <div style={{ fontFamily: "system-ui, -apple-system, Segoe UI, Roboto, sans-serif", background: "#F5F6FA" }}>
      {/* Page Header */}
      <div style={{ ...sectionStyle(0), background: "#fff", borderBottom: "1px solid #E8E9EE", padding: "28px 24px 20px", maxWidth: 680, margin: "0 auto" }}>
        <div style={{ fontSize: 26, fontWeight: 700, color: "#111", letterSpacing: "-0.5px" }}>Money HQ</div>
        <div style={{ fontSize: 14, color: "#908C85", marginTop: 2 }}>Your financial snapshot</div>
      </div>

      <div style={{ maxWidth: 680, margin: "0 auto", padding: "0 16px" }}>
        {/* Section 1: Account Balances */}
        <div style={sectionStyle(80)}>
          <div style={{ marginTop: 28, marginBottom: 14, display: "flex", alignItems: "center", justifyContent: "space-between" }}>
            <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: "0.1em", textTransform: "uppercase", color: "#908C85" }}>Account Balances</div>
            <div style={{ background: "#111", color: "#fff", borderRadius: 20, padding: "4px 14px", fontSize: 13, fontWeight: 600, letterSpacing: "-0.2px" }}>
              Net {fmt$(netWorth)}
            </div>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(260px, 1fr))", gap: 12, paddingBottom: 4 }}>
            {rows.map((acc) => {
              const isCredit = acc.kind === "credit";
              const spark = Array.isArray(acc.sparkline) && acc.sparkline.length > 1 ? acc.sparkline : null;
              const sparkData = spark === null ? null : (isCredit ? spark.map(v => -v) : spark);
              let areaD = "", lineD = "";
              if (sparkData !== null) {
                const min = Math.min(...sparkData), max = Math.max(...sparkData), range = max - min || 1;
                const ptStr = sparkData.map((v, i) => {
                  const x = (i / (sparkData.length - 1)) * sparkW;
                  const y = sparkH - ((v - min) / range) * sparkH;
                  return `${x},${y}`;
                }).join("L");
                areaD = `M0,${sparkH} L${ptStr} L${sparkW},${sparkH} Z`;
                lineD = `M${ptStr}`;
              }
              const accent = kindColor[acc.kind] ?? "#3B82F6";
              const mask = typeof acc.mask === "string" ? `••${acc.mask}` : "";
              return (
                <div key={acc.id ?? acc.name} style={{ background: "#fff", border: "1px solid #E8E9EE", borderRadius: 14, padding: "18px 18px 14px", display: "flex", flexDirection: "column", gap: 10, boxShadow: "0 1px 4px rgba(0,0,0,0.04)" }}>
                  <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between" }}>
                    <div>
                      <div style={{ fontSize: 14, fontWeight: 600, color: "#111" }}>{acc.name}</div>
                      <div style={{ fontSize: 12, color: "#908C85", marginTop: 1 }}>{mask}</div>
                    </div>
                    <div style={{ background: accent + "18", color: accent, borderRadius: 20, padding: "3px 10px", fontSize: 11, fontWeight: 600 }}>{kindLabel[acc.kind] ?? acc.kind}</div>
                  </div>
                  <div style={{ fontSize: 22, fontWeight: 700, color: isCredit ? "#EF4444" : "#111", letterSpacing: "-0.5px" }}>
                    {isCredit ? `${fmt$(Math.abs(acc.balance))} owed` : fmt$(acc.balance)}
                  </div>
                  {sparkData === null ? null : (
                    <svg width={sparkW} height={sparkH} viewBox={`0 0 ${sparkW} ${sparkH}`} style={{ overflow: "visible" }}>
                      <defs>
                        <linearGradient id={`sg-${acc.id ?? acc.mask}`} x1="0" y1="0" x2="0" y2="1">
                          <stop offset="0%" stopColor={accent} stopOpacity="0.18"/>
                          <stop offset="100%" stopColor={accent} stopOpacity="0"/>
                        </linearGradient>
                      </defs>
                      <path d={areaD} fill={`url(#sg-${acc.id ?? acc.mask})`}/>
                      <path d={lineD} fill="none" stroke={accent} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"/>
                    </svg>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

components.MoneyHqSpending:
export default function MoneyHqSpending({ slices }) {
  const [mounted, setMounted] = React.useState(false);
  React.useEffect(() => { requestAnimationFrame(() => setMounted(true)); }, []);

  const categoryColor = {
    housing: "#6366F1",
    shopping: "#F59E0B",
    transport: "#3B82F6",
    subscriptions: "#8B5CF6",
    dining: "#EC4899",
    groceries: "#1DB87A",
    coffee: "#92400E",
  };
  const fallbackPalette = ["#6366F1", "#F59E0B", "#3B82F6", "#8B5CF6", "#EC4899", "#1DB87A", "#92400E"];

  const capitalize = (s) => s.charAt(0).toUpperCase() + s.slice(1);
  const spendingSlices = (Array.isArray(slices) ? slices : [])
    .filter((s) => s && typeof s.category === "string" && typeof s.amount === "number")
    .map((s, i) => ({
      category: capitalize(s.category),
      amount: s.amount,
      color: categoryColor[s.category.toLowerCase()] ?? fallbackPalette[i % fallbackPalette.length],
    }))
    .sort((a, b) => b.amount - a.amount);
  const totalSpend = spendingSlices.reduce((s, x) => s + x.amount, 0);
  if (spendingSlices.length === 0 || totalSpend === 0) return null;

  const fmt$ = (cents) => {
    const abs = Math.abs(cents / 100);
    return (cents < 0 ? "-" : "") + "$" + abs.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  };

  const sectionStyle = (delay) => ({
    opacity: mounted ? 1 : 0,
    transform: mounted ? "translateY(0)" : "translateY(18px)",
    transition: `opacity 0.55s ease ${delay}ms, transform 0.55s ease ${delay}ms`,
  });

  const donutSize = 180;
  const donutStroke = 28;
  const r = (donutSize - donutStroke) / 2;
  const circ = 2 * Math.PI * r;

  return (
    <div style={{ fontFamily: "system-ui, -apple-system, Segoe UI, Roboto, sans-serif", background: "#F5F6FA" }}>
      <div style={{ maxWidth: 680, margin: "0 auto", padding: "0 16px" }}>
        {/* Section 2: Spending by Category */}
        <div style={sectionStyle(60)}>
          <div style={{ marginTop: 32, marginBottom: 14 }}>
            <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: "0.1em", textTransform: "uppercase", color: "#908C85" }}>Spending by Category</div>
          </div>
          <div style={{ background: "#fff", border: "1px solid #E8E9EE", borderRadius: 14, padding: "24px 20px", boxShadow: "0 1px 4px rgba(0,0,0,0.04)" }}>
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 20 }}>
              <div style={{ position: "relative", width: donutSize, height: donutSize }}>
                <svg width={donutSize} height={donutSize} viewBox={`0 0 ${donutSize} ${donutSize}`} style={{ transform: "rotate(-90deg)" }}>
                  {spendingSlices.map((s, i) => {
                    const frac = s.amount / totalSpend;
                    const dash = frac * circ;
                    const gap = circ - dash;
                    let prevFrac = 0;
                    for (let j = 0; j < i; j++) prevFrac += spendingSlices[j].amount / totalSpend;
                    const rotation = prevFrac * 360;
                    return (
                      <circle key={s.category} cx={donutSize/2} cy={donutSize/2} r={r}
                        fill="none" stroke={s.color} strokeWidth={donutStroke}
                        strokeDasharray={`${dash} ${gap}`}
                        strokeDashoffset={0}
                        style={{ transform: `rotate(${rotation}deg)`, transformOrigin: `${donutSize/2}px ${donutSize/2}px` }}
                      />
                    );
                  })}
                </svg>
                <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
                  <div style={{ fontSize: 11, color: "#908C85", fontWeight: 500 }}>Total</div>
                  <div style={{ fontSize: 18, fontWeight: 700, color: "#111", letterSpacing: "-0.5px" }}>{fmt$(totalSpend)}</div>
                </div>
              </div>
              <div style={{ width: "100%", display: "grid", gridTemplateColumns: "1fr 1fr", gap: "8px 16px" }}>
                {spendingSlices.map((s) => (
                  <div key={s.category} style={{ display: "flex", alignItems: "center", gap: 8 }}>
                    <div style={{ width: 10, height: 10, borderRadius: 3, background: s.color, flexShrink: 0 }}/>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 12, color: "#111", fontWeight: 500, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{s.category}</div>
                    </div>
                    <div style={{ fontSize: 12, color: "#908C85", whiteSpace: "nowrap" }}>{fmt$(s.amount)}</div>
                    <div style={{ fontSize: 11, color: "#C0BDB8", whiteSpace: "nowrap" }}>{((s.amount / totalSpend) * 100).toFixed(0)}%</div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

