export default function SpendingBreakdown({ data }: { data: { category: string; amount: number }[] }) {
      if (!data || data.length === 0) return null;

      const total = data.reduce((sum, d) => sum + d.amount, 0);
      const sorted = [...data].sort((a, b) => b.amount - a.amount);

      const fmt = (cents: number) => {
        const dollars = cents / 100;
        return dollars.toLocaleString("en-US", { style: "currency", currency: "USD", minimumFractionDigits: 2 });
      };

      const pct = (cents: number) => {
        if (total === 0) return "0%";
        return ((cents / total) * 100).toFixed(1) + "%";
      };

      const capitalize = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);

      const rowStyle: React.CSSProperties = {
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        padding: "10px 0",
        borderBottom: "1px solid var(--vendo-color-border)",
      };

      const labelStyle: React.CSSProperties = {
        fontFamily: "var(--vendo-font-family)",
        fontSize: "var(--vendo-font-size)",
        color: "var(--vendo-color-text)",
      };

      const rightStyle: React.CSSProperties = {
        display: "flex",
        gap: "12px",
        alignItems: "center",
        fontFamily: "var(--vendo-font-family)",
        fontSize: "var(--vendo-font-size)",
      };

      const amountStyle: React.CSSProperties = {
        color: "var(--vendo-color-text)",
        fontVariantNumeric: "tabular-nums",
        minWidth: "80px",
        textAlign: "right",
      };

      const pctStyle: React.CSSProperties = {
        color: "var(--vendo-color-muted)",
        fontVariantNumeric: "tabular-nums",
        minWidth: "44px",
        textAlign: "right",
        fontSize: "13px",
      };

      const totalRowStyle: React.CSSProperties = {
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        padding: "12px 0 0 0",
      };

      const totalLabelStyle: React.CSSProperties = {
        fontFamily: "var(--vendo-font-family)",
        fontSize: "var(--vendo-font-size)",
        color: "var(--vendo-color-text)",
        fontWeight: 600,
      };

      const totalAmountStyle: React.CSSProperties = {
        fontFamily: "var(--vendo-font-family)",
        fontSize: "var(--vendo-font-size)",
        color: "var(--vendo-color-text)",
        fontVariantNumeric: "tabular-nums",
        fontWeight: 600,
      };

      return (
        <div style={{ width: "100%" }}>
          {sorted.map((item) => (
            <div key={item.category} style={rowStyle}>
              <span style={labelStyle}>{capitalize(item.category)}</span>
