                <span style={amountStyle}>{fmt(item.amount)}</span>
                <span style={pctStyle}>{pct(item.amount)}</span>
              </div>
            </div>
          ))}
          <div style={totalRowStyle}>
            <span style={totalLabelStyle}>Total</span>
            <span style={totalAmountStyle}>{fmt(total)}</span>
          </div>
        </div>
      );
    }
